window.__finlexDocLoaded(10015,{"id":10015,"articles":[{"id":1000026,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with the auditor's responsibility to prepare audit documentation for an audit of financial statements sufficient to enable an experienced auditor to understand the nature, timing, extent, and results of audit procedures.","seq":0},{"id":1000027,"no":"ISA 230.7–16","heading":"Audit Documentation & 60-Day Assembly Rule","text":"Prepare timely documentation sufficient for an experienced auditor with no prior connection to understand procedures, evidence, and significant judgements (ISA 230.8). Assemble the final audit file on a timely basis — ordinarily not more than 60 days after the auditor's report date (ISA 230.A21).","seq":1},{"id":1000028,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
